package fs

import (
	"context"
	"fmt"
	"io/fs"
	"path"

	"go.uber.org/zap"
)

// FSSource produces implementations of fs.FS.
// A single FS can be produced via Get or a channel
// may be provided to Subscribe in order to received
// new instances when new state becomes available.
type FSSource interface {
	fmt.Stringer

	// Get builds a single instance of an fs.FS
	Get() (fs.FS, error)

	// Subscribe feeds implementations of fs.FS onto the provided channel.
	// It should block until the provided context is cancelled (it will be called in a goroutine).
	// It should close the provided channel before it returns.
	Subscribe(context.Context, chan<- fs.FS)
}

// Store is an implementation of storage.Store backed by an FSSource.
// The store subscribes to the source for instances of fs.FS with new contents.
// When a new fs is received the contents is fetched and built into a snapshot
// of Flipt feature flag state.
type Store struct {
	*syncedStore

	logger *zap.Logger
	source FSSource

	// notify is used for test purposes
	// it is invoked if defined when a snapshot update finishes
	notify func()

	cancel context.CancelFunc
	done   chan struct{}
}

func (l *Store) updateSnapshot(fs fs.FS) error {
	storeSnapshot, err := snapshotFromFS(l.logger, fs)
	if err != nil {
		return err
	}

	l.mu.Lock()
	l.storeSnapshot = storeSnapshot
	l.mu.Unlock()

	// NOTE: this is really just a trick for unit tests
	// It is used to signal that an update occurred
	// so we dont have to e.g. sleep to know when
	// to check state.
	if l.notify != nil {
		l.notify()
	}

	return nil
}

// NewStore constructs and configure a Store.
// The store creates a background goroutine which feeds a channel of fs.FS.
func NewStore(logger *zap.Logger, source FSSource) (*Store, error) {
	store := &Store{
		syncedStore: &syncedStore{},
		logger:      logger,
		source:      source,
		done:        make(chan struct{}),
	}

	// get an initial FS from source.
	f, err := source.Get()
	if err != nil {
		return nil, err
	}

	if err := store.updateSnapshot(f); err != nil {
		return nil, err
	}

	var ctx context.Context
	ctx, store.cancel = context.WithCancel(context.Background())

	ch := make(chan fs.FS)
	go source.Subscribe(ctx, ch)

	go func() {
		defer close(store.done)
		for fs := range ch {
			logger.Debug("received new fs")

			if err = store.updateSnapshot(fs); err != nil {
				logger.Error("failed updating snapshot", zap.Error(err))
				continue
			}

			logger.Debug("updated latest fs")
		}

		logger.Info("source subscription closed")
	}()

	return store, nil
}

// Close cancels the polling routine and waits for the routine to return.
func (l *Store) Close() error {
	l.cancel()

	<-l.done

	return nil
}

// String returns an identifier string for the store type.
func (l *Store) String() string {
	return path.Join("filesystem", l.source.String())
}

package ext

import (
	"errors"
)

type Document struct {
	Version   string     `yaml:"version,omitempty"`
	Namespace string     `yaml:"namespace,omitempty"`
	Flags     []*Flag    `yaml:"flags,omitempty"`
	Segments  []*Segment `yaml:"segments,omitempty"`
}

type Flag struct {
	Key         string     `yaml:"key,omitempty"`
	Name        string     `yaml:"name,omitempty"`
	Type        string     `yaml:"type,omitempty"`
	Description string     `yaml:"description,omitempty"`
	Enabled     bool       `yaml:"enabled"`
	Variants    []*Variant `yaml:"variants,omitempty"`
	Rules       []*Rule    `yaml:"rules,omitempty"`
	Rollouts    []*Rollout `yaml:"rollouts,omitempty"`
}

type Variant struct {
	Key         string      `yaml:"key,omitempty"`
	Name        string      `yaml:"name,omitempty"`
	Description string      `yaml:"description,omitempty"`
	Attachment  interface{} `yaml:"attachment,omitempty"`
}

type Rule struct {
	Segment       *SegmentEmbed   `yaml:"segment,omitempty"`
	Rank          uint            `yaml:"rank,omitempty"`
	Distributions []*Distribution `yaml:"distributions,omitempty"`
}

type Distribution struct {
	VariantKey string  `yaml:"variant,omitempty"`
	Rollout    float32 `yaml:"rollout,omitempty"`
}

type Rollout struct {
	Description string         `yaml:"description,omitempty"`
	Segment     *SegmentRule   `yaml:"segment,omitempty"`
	Threshold   *ThresholdRule `yaml:"threshold,omitempty"`
}

type SegmentRule struct {
	Key      string   `yaml:"key,omitempty"`
	Keys     []string `yaml:"keys,omitempty"`
	Operator string   `yaml:"operator,omitempty"`
	Value    bool     `yaml:"value,omitempty"`
}

type ThresholdRule struct {
	Percentage float32 `yaml:"percentage,omitempty"`
	Value      bool    `yaml:"value,omitempty"`
}

type Segment struct {
	Key         string        `yaml:"key,omitempty"`
	Name        string        `yaml:"name,omitempty"`
	Description string        `yaml:"description,omitempty"`
	Constraints []*Constraint `yaml:"constraints,omitempty"`
	MatchType   string        `yaml:"match_type,omitempty"`
}

type Constraint struct {
	Type        string `yaml:"type,omitempty"`
	Property    string `yaml:"property,omitempty"`
	Operator    string `yaml:"operator,omitempty"`
	Value       string `yaml:"value,omitempty"`
	Description string `yaml:"description,omitempty"`
}

type SegmentEmbed struct {
	IsSegment `yaml:"-"`
}

// MarshalYAML tries to type assert to either of the following types that implement
// IsSegment, and returns the marshaled value.
func (s *SegmentEmbed) MarshalYAML() (interface{}, error) {
	switch t := s.IsSegment.(type) {
	case SegmentKey:
		return string(t), nil
	case *Segments:
		sk := &Segments{
			Keys:            t.Keys,
			SegmentOperator: t.SegmentOperator,
		}
		return sk, nil
	}

	return nil, errors.New("failed to marshal to string or segmentKeys")
}

// UnmarshalYAML attempts to unmarshal a string or `SegmentKeys`, and fails if it can not
// do so.
func (s *SegmentEmbed) UnmarshalYAML(unmarshal func(interface{}) error) error {
	var sk SegmentKey

	if err := unmarshal(&sk); err == nil {
		s.IsSegment = sk
		return nil
	}

	var sks *Segments
	if err := unmarshal(&sks); err == nil {
		s.IsSegment = sks
		return nil
	}

	return errors.New("failed to unmarshal to string or segmentKeys")
}

// IsSegment is used to unify the two types of segments that can come in
// from the import.
type IsSegment interface {
	IsSegment()
}

type SegmentKey string

func (s SegmentKey) IsSegment() {}

type Segments struct {
	Keys            []string `yaml:"keys,omitempty"`
	SegmentOperator string   `yaml:"operator,omitempty"`
}

func (s *Segments) IsSegment() {}

package cue

import (
	_ "embed"
	"errors"
	"fmt"
	"strings"

	"go.flipt.io/flipt/internal/ext"
	"gopkg.in/yaml.v3"

	"cuelang.org/go/cue"
	"cuelang.org/go/cue/cuecontext"
	cueerrors "cuelang.org/go/cue/errors"
	"cuelang.org/go/encoding/yaml"
)

var (
	//go:embed flipt.cue
	cueFile             []byte
	ErrValidationFailed = errors.New("validation failed")
)

// Location contains information about where an error has occurred during cue
// validation.
type Location struct {
	File   string `json:"file,omitempty"`
	Line   int    `json:"line"`
	Column int    `json:"column"`
}

	return nil
}

func referenceLocations(root *yaml.Node) map[string]struct{ Line, Column int } {
	type pos struct{ Line, Column int }
	out := map[string]pos{}
	if root == nil || len(root.Content) == 0 {
		return out
	}
	get := func(n *yaml.Node, key string) *yaml.Node {
		if n == nil {
			return nil
		}
		for i := 0; i+1 < len(n.Content); i += 2 {
			if n.Content[i].Value == key {
				return n.Content[i+1]
			}
		}
		return nil
	}
	flags := get(root.Content[0], "flags")
	if flags == nil {
		return out
	}
	for _, fn := range flags.Content {
		key := get(fn, "key")
		rules := get(fn, "rules")
		if key == nil || rules == nil {
			continue
		}
		for i, rn := range rules.Content {
			out[fmt.Sprintf("rule:%s:%d", key.Value, i)] = pos{rn.Line, rn.Column}
		}
	}
	return out
}
